/* WOMB_EAST_VALVE_BEGIN */
(() => {
  const column = 32, row = 28, level = 8;
  const tones = {
    bed:[83,27,22], root:[109,40,28], bone:[154,103,70],
    pale:[185,132,91], edge:[125,70,46]
  };
  const texels = /* VALVE_SWATCHES_BEGIN */ {
    "bed": "",
    "root": "",
    "bone": "",
    "pale": "",
    "edge": ""
  } /* VALVE_SWATCHES_END */;
  const names = Object.keys(tones);
  const tile = 64, interior = tile - 4;
  const width = tile * names.length;
  const clamp = (n, low, high) => Math.max(low, Math.min(high, n));
  const margin = (u, size) => (2.5 + u * (interior - 1)) / size;

  function surfaceAtlas() {
    const texture = Z(e0(ctx => {
      const image = ctx.createImageData(width,tile);
      names.forEach((name,index) => {
        const raw = texels[name] && atob(texels[name]);
        const tone = tones[name];
        for (let y = 0; y < tile; y++) for (let x = 0; x < tile; x++) {
          const u = clamp(x-2,0,interior-1), v = clamp(y-2,0,interior-1);
          const source = 2 * (v * interior + u);
          const target = 4 * (y * width + index * tile + x);
          if (raw) {
            const pixel = raw.charCodeAt(source) | raw.charCodeAt(source+1)<<8;
            image.data[target] = (pixel >> 11) * 255/31;
            image.data[target+1] = (pixel >> 5 & 63) * 255/63;
            image.data[target+2] = (pixel & 31) * 255/31;
          } else {
            const grain = (u * 19 + v * 77 + u * v * 3) % 31 - 14;
            const grainLong = ((u * 17 + Math.floor(v / 3) * 47) % 24 - 11) * .56;
            for (let c=0;c<3;c++) image.data[target+c] = tone[c] + grain*.46 + grainLong;
          }
          image.data[target+3] = 255;
        }
      });
      ctx.putImageData(image,0,0);
    },width,tile));
    texture.name = "wombValveMineralAtlas";
    texture.colorSpace = ha;
    texture.minFilter = YC;
    texture.generateMipmaps = true;
    return texture;
  }

  function ribs(scene,x,floor,z,height) {
    const positions = [], uv = [], colors = [];
    function tube(name, knots, sides = 7) {
      const rings = [];
      const atlasStart = names.indexOf(name) * tile / width;
      for (let i=0; i<knots.length; i++) {
        const [px,py,pz,span,depth,brightness=1] = knots[i];
        const prev=knots[Math.max(0,i-1)], next=knots[Math.min(knots.length-1,i+1)];
        const dx = next[0]-prev[0], dy = next[1]-prev[1], length = Math.hypot(dx,dy) || 1;
        const ring = [];
        for (let j=0;j<=sides;j++) {
          const angle=(j%sides)*Math.PI*2/sides;
          const across=Math.cos(angle), front=Math.sin(angle);
          const chip=1+Math.sin(i*2.59+j%sides*53.3)*.10;
          const vary=1+Math.sin(i*1.19+j%sides*.91)*.073;
          const shade=brightness*vary*(.52+.42*Math.max(0,front)+.06*Math.max(0,across));
          ring.push({
            pos:[px+across*span*chip*dy/length,py-across*span*chip*dx/length,pz+front*depth*chip],
            tex:[atlasStart+margin(j/sides,width),margin(i/(knots.length-1),tile)],
            shade
          });
        }
        rings.push(ring);
      }
      const push = vertex => {
        positions.push(...vertex.pos);
        uv.push(...vertex.tex);
        colors.push(vertex.shade,vertex.shade*.96,vertex.shade*.91);
      };
      for (let i=0;i<rings.length-1;i++) for(let j=0;j<sides;j++){
        const a=rings[i][j], b=rings[i+1][j], c=rings[i+1][j+1], d=rings[i][j+1];
        for (const vertex of [a,b,c,a,c,d]) push(vertex);
      }
    }

    // Use the native arch to place the crust outside the original aperture.
    // The fleshy hinge rotates in its own cell behind both stationary ribs.
    const scale=height/Zt;
    const arch=uZ();
    const peak=arch[arch.length-1].y*scale;
    function course(extension,bed) {
      const climb = side => {
        const below=arch[0].y * scale;
        const lead=side<0 ? .032 : -.003;
        const floorRadii=bed?[.158,.144,.104,.099,.092,.075]:[.010,.032,.048,.033,.041,.039];
        const points=[.017,.142,.29,.53,.86,below-.28].map((y,i)=>[
          side*(1+extension+lead+Math.sin(i*1.7+side)*.018+(i<3&&bed?.06*(3-i)/3:0)),y,
          1.103+(bed?0:.060)+Math.sin(i*1.6+side)*.022,
          floorRadii[i],bed?.114:.051,bed?.96:.68+i*.073
        ]);
        for(let i=0;i<arch.length;i++) {
          const p=arch[i];
          const jitter=Math.sin(i*1.93+side*.8)*.027;
          const extra=extension+jitter+lead*(1-i/(arch.length-1));
          const width=bed?.106+Math.cos(i*1.72)*.027:.039+Math.sin(i*1.59+side)*.017;
          points.push([side*(p.x-p.nx*extra),p.y*scale-p.ny*extra,
            1.078+(bed?0:.072)+Math.sin(i*1.14+side)*.037,
            width,bed?.111:.050,bed?.95:1.13-Math.abs(i-5)*.041]);
        }
        return points;
      };
      const left = climb(-1), right = climb(1).reverse();
      return [...left,...right.slice(1)];
    }
    tube("bed",course(.166,true));
    tube("bone",course(.098,false));

    // On the west shoulder, a second weathered rib surfaces and dives into
    // the mantle. The east shoulder has only a shallow hooked fragment.
    tube("root",[
      [-1.27,.48,1.052,.009,.023],[-1.33,.75,1.078,.073,.074],
      [-1.295,1.12,1.093,.105,.100],[-1.29,1.52,1.100,.131,.084],
      [-1.18,1.81,1.105,.111,.095],[-1.12,2.115,1.109,.119,.098],
      [-.896,2.396,1.111,.129,.099],[-.697,2.635,1.105,.112,.086],
      [-.45,peak+.172,1.098,.076,.072],[-.08,peak+.182,1.090,.082,.059],
      [.13,peak+.173,1.095,.080,.051],[.30,peak+.118,1.075,.018,.039]
    ]);
    tube("pale",[
      [-1.311,.77,1.112,.008,.009,.64],[-1.326,.90,1.144,.034,.048,.82],
      [-1.30,1.11,1.174,.066,.070,.95],[-1.274,1.20,1.182,.045,.060,.88],
      [-1.282,1.41,1.166,.036,.061,.97],[-1.284,1.61,1.186,.067,.063,.98],
      [-1.189,1.80,1.155,.042,.062,1.02],[-1.109,2.091,1.179,.054,.056,1.08],
      [-.913,2.355,1.171,.062,.060,1.15],[-.759,2.51,1.155,.046,.051,1.13],
      [-.667,2.616,1.165,.069,.052,1.10],[-.449,peak+.175,1.162,.041,.048,1.06],
      [-.102,peak+.177,1.146,.040,.051,1.05],[.027,peak+.181,1.145,.066,.065,.96],
      [.132,peak+.164,1.144,.042,.042,.93],[.283,peak+.133,1.103,.011,.015,.60]
    ]);
    tube("edge",[
      [1.129,1.08,1.105,.008,.010],[1.151,1.29,1.132,.030,.035],
      [1.134,1.54,1.128,.056,.065],[1.177,1.74,1.144,.045,.041],
      [1.225,1.90,1.12,.014,.020],[1.22,1.98,1.066,.007,.008]
    ]);
    tube("pale",[
      [-.132,peak+.177,1.130,.034,.040,.96],[.004,peak+.185,1.156,.053,.063,1.04],
      [-.031,Math.min(2.890,peak+.281),1.151,.037,.050,1.10],
      [-.066,Math.min(2.942,peak+.332),1.133,.023,.031,1.03],
      [-.096,Math.min(2.955,peak+.357),1.088,.006,.010,.76]
    ]);
    tube("bone",[
      [-1.295,1.45,1.160,.019,.033,.81],[-1.347,1.538,1.181,.034,.042,1.05],
      [-1.382,1.622,1.172,.025,.039,1.08],[-1.389,1.699,1.115,.006,.009,.73]
    ],6);

    for (const side of [-1,1]) {
      const roots=side<0?[-.06,.02,.105,.195,.258]:[-.014,.08,.164,.246];
      roots.forEach((value,i)=>{
        const s=side*(1.12+value);
        const shade= .86 + (i%4)*.087;
        tube(i%4===0?"edge":"root",[
          [s,.009,1.15+i*.036,.011,.020,shade*.69],
          [side*(1.18+value*.91),.052+i%2*.037,1.203+i*.022,.044,.053,shade*.89],
          [side*(1.144+value*.60),.141,1.181+i%2*.026,.037,.041,shade],
          [side*(1.121+value*.45),.228+i*.050,1.155,.047,.042,shade*.93],
          [side*(1.10+value*.38),.327+i*.034,1.113,.008,.010,shade*.74]
        ],6);
      });
    }

    const geometry=Z(new h0());
    geometry.setAttribute("position",new y0(new Float32Array(positions),3));
    geometry.setAttribute("uv",new y0(new Float32Array(uv),2));
    geometry.setAttribute("color",new y0(new Float32Array(colors),3));
    const material=Z(new $e({map:surfaceAtlas(),vertexColors:true,toneMapped:false,side:hi}));
    const model=new pt(geometry,material);
    model.name="wombEastValveRibs";
    model.position.set(x,floor,z);
    scene.add(model);
  }

  const decorate=FJ;
  FJ=function(scene,map) {
    decorate.apply(this,arguments);
    if (T.level!==level || v.grid[row]?.[column]!=="+") return;
    const door=v.doors[column+","+row];
    if (!door?.flesh || door.axis!=="z" || door.locked || !door.leaves) return;
    const {x,y,z}=door.mesh.position;
    ribs(scene,x,y,z,Math.min(Zt,AA(column,row)-y));
  };
})();
/* WOMB_EAST_VALVE_END */
